package palindrome

import (
	"errors"
	"strconv"
)

// Product holds a palindromic product value together with all of its
// factorizations as pairs of factors within the given range.
type Product struct {
	Value          int
	Factorizations [][2]int
}

// Products returns the smallest and largest palindromic numbers that are the
// product of two numbers within [fmin, fmax] (both inclusive), along with
// all factor pairs for each. It returns an error if fmin > fmax or if no
// palindromic product exists in the range.
func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, errors.New("fmin > fmax")
	}

	var min, max Product
	found := false

	for i := fmin; i <= fmax; i++ {
		for j := i; j <= fmax; j++ {
			p := i * j
			if !isPalindrome(p) {
				continue
			}
			if !found || p < min.Value {
				min = Product{p, [][2]int{{i, j}}}
				found = true
			} else if p == min.Value {
				min.Factorizations = append(min.Factorizations, [2]int{i, j})
			}
			if !found || p > max.Value {
				max = Product{p, [][2]int{{i, j}}}
			} else if p == max.Value {
				max.Factorizations = append(max.Factorizations, [2]int{i, j})
			}
		}
	}

	if !found {
		return Product{}, Product{}, errors.New("no palindromes found")
	}
	return min, max, nil
}

// isPalindrome reports whether n reads the same forwards and backwards.
func isPalindrome(n int) bool {
	s := strconv.Itoa(n)
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		if s[i] != s[j] {
			return false
		}
	}
	return true
}
